        m.insert("currency".to_string(), code);
        m.insert("amount".to_string(), self.safe_number_k(transfer.clone(), "amount", &[]));
        m.insert("fromAccount".to_string(), fromAccount);
        m.insert("toAccount".to_string(), toAccount);
